INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 13, 'theory', 'Quiz: methods and properties');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 0, 'Which method does Python call on a when it evaluates a + b?', '["a.__plus__(b)", "a.__add__(b)", "a.add(b)", "b.__add__(a)"]', 1, 'The + operator is shorthand for calling the magic method __add__ on the left operand.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 1, 'You defined __eq__ but not __hash__. What happens on {obj: 1}?', '["Everything works", "TypeError: unhashable type", "The object is compared by id", "Python adds __hash__ itself"]', 1, 'If __eq__ is defined and __hash__ is not, Python disables hashing: the object cannot be used as a key.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 2, 'What does the @property decorator do above a method area?', '["Makes the method private", "Lets you read area as an attribute, without parentheses", "Forbids changing the object", "Makes the method faster"]', 1, 'A property looks like an attribute: obj.area instead of obj.area(); the value is computed on access.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 3, 'What is @classmethod most often used for?', '["For hidden data", "For alternative constructors, such as from_string", "For sorting", "To make the method run faster"]', 1, 'A class method receives cls and returns a new object in a different way than the main constructor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 4, 'What must a class define so that sorted(list_of_objects) works without the key parameter?', '["__len__", "__lt__", "__str__", "__hash__"]', 1, 'sorted compares elements with the < operator, that is, with the __lt__ method.');
